def transform(grid):
    colors = {}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v != 0: colors.setdefault(v, []).append((r,c))
    if not colors: return [row[:] for row in grid]
    def score(v):
        pts=colors[v]
        area=(max(r for r,c in pts)-min(r for r,c in pts)+1)*(max(c for r,c in pts)-min(c for r,c in pts)+1)
        return len(pts)/area
    color=max(colors,key=score)
    return [[color if v else 0 for v in row] for row in grid]

